// redactFetchTarget returns a safe-to-log version of the target.
func redactFetchTarget(target string) string {
	if isFetchURL(target) {
		return strategy.RedactURL(target)
	}
	return target
}

// isFetchURL returns true if the target looks like a URL rather than a git remote name.
func isFetchURL(target string) bool {
	return strings.Contains(target, "://") || strings.Contains(target, "@")
